const cfg = $input.first().json;
const helpers = this.helpers;
const UA = 'OptimityAuditBot/1.0 (authorised site audit)';
const maxPages = Math.min(Number(cfg.maxPages) || 10, 25);
const delayMs = Math.max(Number(cfg.crawlDelayMs) || 500, 250);
const maxLinkChecks = 30;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const parseUrl = (u) => { const m = String(u).match(/^(https?):\/\/([^\/?#:]+)(?::(\d+))?([^?#]*)(\?[^#]*)?/i); if (!m) return null; return { protocol: m[1].toLowerCase(), hostname: m[2].toLowerCase(), port: m[3] || '', pathname: m[4] || '/', search: m[5] || '' }; };
const originOf = (p) => p.protocol + '://' + p.hostname + (p.port ? ':' + p.port : '');
const finalize = (u) => { const p = parseUrl(String(u).split('#')[0]); if (!p) return null; const segs = []; p.pathname.split('/').forEach((s) => { if (s === '..') { if (segs.length > 1) segs.pop(); } else if (s !== '.') { segs.push(s); } }); let path = segs.join('/'); if (path.charAt(0) !== '/') path = '/' + path; return originOf(p) + path + p.search; };
const norm = (href, base) => { const h = String(href).trim(); if (/^[a-zA-Z][a-zA-Z0-9+.-]*:/.test(h)) { return /^https?:/i.test(h) ? finalize(h) : null; } const b = parseUrl(base); if (!b) return null; if (h.indexOf('//') === 0) return finalize(b.protocol + ':' + h); const hh = h.split('#')[0]; if (hh === '') return finalize(base); if (hh.charAt(0) === '/') return finalize(originOf(b) + hh); if (hh.charAt(0) === '?') return finalize(originOf(b) + b.pathname + hh); return finalize(originOf(b) + b.pathname.replace(/[^\/]*$/, '') + hh); };
const start = parseUrl(cfg.startUrl);
if (!start) { throw new Error('startUrl must be a valid http(s) URL.'); }
const host = start.hostname;
if (host !== String(cfg.allowedDomain || '').trim().toLowerCase()) {
  throw new Error('Start URL host does not match the authorised domain. Audit stopped.');
}
const notes = [];
const findings = [];
let fid = 0;
const snip = (s) => String(s).replace(/\s+/g, ' ').slice(0, 160);
const add = (url, category, severity, rule, message, evidence, fix) => {
  fid += 1;
  findings.push({ id: 'F' + String(fid).padStart(3, '0'), url: url, category: category, severity: severity, rule: rule, message: message, evidence: String(evidence || '').slice(0, 260), fix: fix });
};
const fetchUrl = async (url, method) => {
  try {
    const res = await helpers.httpRequest({ method: method || 'GET', url: url, headers: { 'User-Agent': UA }, timeout: 10000, returnFullResponse: true, ignoreHttpStatusErrors: true, json: false });
    return { status: res.statusCode, type: String((res.headers || {})['content-type'] || ''), body: String(res.body || '') };
  } catch (e) {
    return { status: 0, type: '', body: '', error: String(e.message || e).slice(0, 120) };
  }
};
const strip = (s) => String(s).replace(/<script[^]*?<\/script>/gi, ' ').replace(/<style[^]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
const attrs = (tag) => {
  const o = {};
  const body = String(tag).replace(/^<[a-zA-Z0-9]+/, '').replace(/\/?>$/, '');
  const re = /([a-zA-Z_:][-a-zA-Z0-9_:.]*)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'>]+)))?/g;
  let m;
  while ((m = re.exec(body)) !== null) {
    o[m[1].toLowerCase()] = m[2] !== undefined ? m[2] : (m[3] !== undefined ? m[3] : (m[4] !== undefined ? m[4] : ''));
  }
  return o;
};

const disallow = [];
const robots = await fetchUrl(originOf(start) + '/robots.txt', 'GET');
if (robots.status === 200) {
  let applies = false;
  robots.body.split(String.fromCharCode(10)).forEach((raw) => {
    const line = raw.split('#')[0].trim();
    const m = line.match(/^([A-Za-z-]+)\s*:\s*(.*)$/);
    if (!m) return;
    const key = m[1].toLowerCase();
    if (key === 'user-agent') { applies = m[2].trim() === '*'; }
    else if (key === 'disallow' && applies && m[2].trim()) { disallow.push(m[2].trim()); }
  });
  notes.push('robots.txt honoured (' + disallow.length + ' disallow rule(s) for all agents).');
} else {
  notes.push('No robots.txt found (HTTP ' + robots.status + ').');
}
const allowedByRobots = (u) => {
  const pu = parseUrl(u);
  if (!pu) return false;
  return !disallow.some((d) => pu.pathname.indexOf(d) === 0);
};

const statusMap = {};
const errMap = {};
const linkMap = {};
const emails = {};
const pages = [];
const seen = {};
const queue = [];
const startNorm = finalize(cfg.startUrl);
queue.push(startNorm);
seen[startNorm] = true;
let fetched = 0;

while (queue.length > 0 && fetched < maxPages) {
  const url = queue.shift();
  if (!allowedByRobots(url)) { notes.push('Skipped by robots.txt: ' + url); continue; }
  if (fetched > 0) await sleep(delayMs);
  fetched += 1;
  const r = await fetchUrl(url, 'GET');
  statusMap[url] = r.status;
  if (r.status === 0 || r.status >= 400) {
    errMap[url] = r.error || ('HTTP ' + r.status);
    if (!linkMap[url]) add(url, 'links', 'high', 'broken-page', 'Start page could not be loaded', errMap[url], 'Check the URL and that the site is reachable.');
    continue;
  }
  if (r.type && r.type.toLowerCase().indexOf('html') === -1) { notes.push('Skipped non-HTML resource: ' + url); continue; }
  const html = r.body;

  const titleM = html.match(/<title[^>]*>([^]*?)<\/title>/i);
  const title = titleM ? strip(titleM[1]) : '';
  let desc = null;
  let viewport = false;
  (html.match(/<meta\b[^>]*>/gi) || []).forEach((m) => {
    const a = attrs(m);
    const n = String(a.name || '').toLowerCase();
    if (n === 'description') desc = a.content || '';
    if (n === 'viewport') viewport = true;
  });
  const lang = attrs((html.match(/<html\b[^>]*>/i) || [''])[0]).lang;

  if (!title) add(url, 'seo', 'high', 'missing-title', 'Page has no <title>', 'No <title> element found', 'Add a unique, descriptive title (under 60 characters).');
  else if (title.length > 60) add(url, 'seo', 'low', 'long-title', 'Title is longer than 60 characters', title, 'Shorten the title so it is not truncated in search results.');
  if (desc === null || desc === '') add(url, 'seo', 'medium', 'missing-meta-description', 'Meta description is missing or empty', 'No <meta name="description"> content', 'Add a 50-160 character description.');
  else if (desc.length < 50 || desc.length > 160) add(url, 'seo', 'low', 'meta-description-length', 'Meta description length is ' + desc.length + ' characters', desc, 'Aim for 50-160 characters.');
  if (!lang) add(url, 'accessibility', 'medium', 'html-lang-missing', 'The html element has no lang attribute (WCAG 3.1.1)', '<html> without lang', 'Add lang="en" (or the correct language).');
  if (!viewport) add(url, 'seo', 'low', 'missing-viewport', 'No viewport meta tag (mobile rendering)', 'No <meta name="viewport">', 'Add <meta name="viewport" content="width=device-width, initial-scale=1">.');

  const levels = [];
  const hRe = /<h([1-6])\b/gi;
  let hm;
  while ((hm = hRe.exec(html)) !== null) { levels.push(Number(hm[1])); }
  const h1Count = levels.filter((l) => l === 1).length;
  if (h1Count === 0) add(url, 'accessibility', 'medium', 'missing-h1', 'Page has no H1 heading', 'Found headings: ' + (levels.length ? levels.map((l) => 'h' + l).join(',') : 'none'), 'Add one H1 that describes the page.');
  else if (h1Count > 1) add(url, 'accessibility', 'low', 'multiple-h1', 'Page has ' + h1Count + ' H1 headings', h1Count + ' <h1> elements', 'Use a single H1 per page.');
  for (let i = 1; i < levels.length; i++) {
    if (levels[i] - levels[i - 1] > 1) { add(url, 'accessibility', 'low', 'heading-order', 'Heading levels skip (h' + levels[i - 1] + ' to h' + levels[i] + ')', 'Heading sequence: ' + levels.map((l) => 'h' + l).join(','), 'Do not skip heading levels.'); break; }
  }

  (html.match(/<img\b[^>]*>/gi) || []).forEach((img) => {
    const ia = attrs(img);
    if (ia.alt === undefined) add(url, 'accessibility', 'high', 'img-missing-alt', 'Image has no alt attribute (WCAG 1.1.1)', snip(img), 'Add descriptive alt text, or alt="" if purely decorative.');
    else if (/\.(png|jpe?g|gif|svg|webp)$/i.test(ia.alt.trim())) add(url, 'accessibility', 'low', 'img-filename-alt', 'Alt text looks like a file name', snip(img), 'Describe the image content instead of the file name.');
  });

  (html.match(/<a\b[^>]*>[^]*?<\/a>/gi) || []).forEach((a) => {
    const openTag = a.match(/^<a\b[^>]*>/i)[0];
    const at = attrs(openTag);
    const inner = a.replace(/^<a\b[^>]*>/i, '').replace(/<\/a>$/i, '');
    const text = strip(inner);
    const imgTag = (inner.match(/<img\b[^>]*>/i) || [''])[0];
    const hasName = text.length > 0 || !!at['aria-label'] || !!at.title || (imgTag !== '' && !!attrs(imgTag).alt);
    if (at.href === undefined) return;
    if (!hasName) add(url, 'accessibility', 'high', 'link-no-name', 'Link has no accessible name (WCAG 2.4.4)', snip(a), 'Add link text or an aria-label.');
    else if (/^(click here|here|read more|more|link)$/i.test(text)) add(url, 'accessibility', 'low', 'link-generic-text', 'Link text is not descriptive', snip(a), 'Use link text that makes sense out of context.');
    if (at.href === '' || at.href === '#') { add(url, 'content', 'low', 'placeholder-link', 'Link points to an empty or "#" target', snip(openTag), 'Point the link to a real destination or remove it.'); return; }
    const target = norm(at.href, url);
    if (!target) return;
    (linkMap[target] = linkMap[target] || []).push(url);
    const tu = parseUrl(target);
    if (tu && tu.hostname === host && !seen[target] && !/\.(pdf|jpe?g|png|gif|svg|webp|zip|css|js|ico|mp4)$/i.test(tu.pathname)) { seen[target] = true; queue.push(target); }
  });

  const labelFor = {};
  (html.match(/<label\b[^>]*>/gi) || []).forEach((l) => { const f = attrs(l)['for']; if (f) labelFor[f] = true; });
  const labelBlocks = html.match(/<label\b[^>]*>[^]*?<\/label>/gi) || [];
  (html.match(/<(input|select|textarea)\b[^>]*>/gi) || []).forEach((f) => {
    const fa = attrs(f);
    const t = String(fa.type || 'text').toLowerCase();
    if (['hidden', 'submit', 'button', 'image', 'reset'].indexOf(t) !== -1) return;
    const labelled = !!fa['aria-label'] || !!fa['aria-labelledby'] || !!fa.title || (fa.id && labelFor[fa.id]) || labelBlocks.some((b) => b.indexOf(f) !== -1);
    if (!labelled) add(url, 'accessibility', 'high', 'form-field-no-label', 'Form field has no associated label (WCAG 1.3.1 / 3.3.2)', snip(f), 'Add a <label for="id"> or an aria-label.');
  });

  const text = strip(html.replace(/<head[^]*?<\/head>/i, ' '));
  const words = text ? text.split(' ').length : 0;
  const ph = text.match(/lorem ipsum|\bTODO\b|\bTBD\b|coming soon|under construction/i);
  if (ph) add(url, 'content', 'medium', 'placeholder-content', 'Placeholder or unfinished text found', 'Matched "' + ph[0] + '" near: ' + text.slice(Math.max(0, ph.index - 40), ph.index + 60), 'Replace with final content.');
  if (words < 50) add(url, 'content', 'low', 'thin-content', 'Page has very little text (' + words + ' words)', text.slice(0, 120), 'Check whether the page is intentionally minimal.');
  (text.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g) || []).forEach((e) => {
    const k = e.toLowerCase();
    (emails[k] = emails[k] || []).push(url);
  });
  pages.push({ url: url, status: r.status, title: title, words: words, sample: text.slice(0, 700) });
}

pages.forEach((p) => { statusMap[p.url] = p.status; });
const targets = Object.keys(linkMap);
const toCheck = targets.filter((t) => statusMap[t] === undefined && allowedByRobots(t)).slice(0, maxLinkChecks);
const unchecked = targets.filter((t) => statusMap[t] === undefined).length - toCheck.length;
for (const t of toCheck) {
  await sleep(delayMs);
  let lr = await fetchUrl(t, 'HEAD');
  if (lr.status === 0 || lr.status === 403 || lr.status === 405 || lr.status === 501) lr = await fetchUrl(t, 'GET');
  statusMap[t] = lr.status;
  if (lr.error) errMap[t] = lr.error;
}
if (unchecked > 0) notes.push(unchecked + ' link target(s) not checked (limit of ' + maxLinkChecks + ' extra checks per run).');
targets.forEach((t) => {
  const s = statusMap[t];
  if (s === 0 || s >= 400) {
    const srcs = linkMap[t].filter((v, i, arr) => arr.indexOf(v) === i);
    add(srcs[0], 'links', (s === 404 || s === 410) ? 'high' : 'medium', 'broken-link', 'Broken link: ' + (s ? 'HTTP ' + s : 'unreachable'), 'Target: ' + t + ' | found on: ' + srcs.slice(0, 3).join(', '), 'Update or remove the link.');
  }
});

const titleGroups = {};
pages.forEach((p) => { if (p.title) { (titleGroups[p.title] = titleGroups[p.title] || []).push(p.url); } });
Object.keys(titleGroups).forEach((t) => {
  if (titleGroups[t].length > 1) add(titleGroups[t][0], 'seo', 'low', 'duplicate-title', 'Same title used on ' + titleGroups[t].length + ' pages', 'Title "' + t + '" on: ' + titleGroups[t].slice(0, 4).join(', '), 'Give each page a unique title.');
});
const emailKeys = Object.keys(emails);
if (emailKeys.length > 1) {
  add(startNorm, 'content', 'low', 'multiple-contact-emails', 'Several different email addresses found - verify this is intended', emailKeys.slice(0, 5).map((e) => e + ' (' + emails[e][0] + ')').join('; '), 'Confirm the addresses are current and consistent.');
}

return [{ json: {
  config: { startUrl: cfg.startUrl, allowedDomain: cfg.allowedDomain, maxPages: maxPages, crawlDelayMs: delayMs },
  stats: { pagesCrawled: pages.length, linksChecked: toCheck.length, findingsTotal: findings.length },
  pages: pages,
  findings: findings,
  notes: notes
} }];

const d = $input.first().json;
const cfg = $('Audit Config').first().json;
const sample = d.pages.slice(0, 8).map((p) => 'URL: ' + p.url + '\nTitle: ' + p.title + '\nText: ' + p.sample).join('\n---\n');
const prompt = 'You are a QA reviewer for website content. Below are text excerpts from pages of one website. List up to 5 POSSIBLE content inconsistencies (conflicting facts, naming, tone, contact details, prices, dates). For each one give: the page URL(s), a short exact quote as evidence, and why it may be a problem. If you find none, reply exactly: No inconsistencies found. Do not invent facts or quotes.\n\n' + sample;
return [{ json: {
  useAI: cfg.useAI === true || String(cfg.useAI) === 'true',
  llmPrompt: prompt
} }];

const d = $('Bounded Crawl & Rule Checks').first().json;
let ai = '';
let aiStatus = 'AI step skipped (AI review not requested). All findings below come from deterministic rules.';
try {
  const o = $('Ask Claude (Anthropic)').first().json;
  const t = o.mergedResponse || (Array.isArray(o.content) && o.content[0] && o.content[0].text) || o.text || '';
  if (t) { ai = String(t).trim(); aiStatus = 'AI notes generated by Claude (Anthropic).'; }
  else { aiStatus = 'AI step failed or returned nothing; rule-based findings are unaffected.'; }
} catch (e) {}
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const sevRank = { high: 0, medium: 1, low: 2 };
const sorted = d.findings.slice().sort((a, b) => sevRank[a.severity] - sevRank[b.severity]);
const counts = { high: 0, medium: 0, low: 0 };
const cats = {};
d.findings.forEach((f) => { counts[f.severity] += 1; cats[f.category] = (cats[f.category] || 0) + 1; });
const byPage = {};
sorted.forEach((f) => { (byPage[f.url] = byPage[f.url] || []).push(f); });
const pageUrls = Object.keys(byPage);
const today = new Date().toISOString().slice(0, 10);
const disclaimer = 'Automated checks cover a subset of common issues and are NOT a full accessibility audit or WCAG certification. Manual testing with assistive technology and expert review are still required. Nothing on the website was modified.';

const md = [];
md.push('# Website Quality & Content Audit');
md.push('');
md.push('- Target: ' + d.config.startUrl);
md.push('- Date: ' + today);
md.push('- Pages crawled: ' + d.stats.pagesCrawled + ' (limit ' + d.config.maxPages + '), extra links checked: ' + d.stats.linksChecked);
md.push('- Findings: ' + d.findings.length + ' (high ' + counts.high + ', medium ' + counts.medium + ', low ' + counts.low + ')');
md.push('');
md.push('> ' + disclaimer);
md.push('');
md.push('## Findings by page');
if (pageUrls.length === 0) md.push('No findings from the automated rules.');
pageUrls.forEach((u) => {
  md.push('');
  md.push('### ' + u);
  byPage[u].forEach((f) => {
    md.push('- **[' + f.severity.toUpperCase() + ']** ' + f.id + ' ' + f.rule + ' (' + f.category + '): ' + f.message);
    md.push('  - Evidence: "' + f.evidence + '"');
    md.push('  - Suggested fix: ' + f.fix);
  });
});
md.push('');
md.push('## AI-assisted content review (unverified interpretation)');
md.push(aiStatus);
if (ai) { md.push(''); md.push(ai); md.push(''); md.push('_AI output may be wrong. Verify against the pages before acting._'); }
md.push('');
md.push('## Crawl notes');
d.notes.forEach((n) => md.push('- ' + n));

const sevColor = { high: '#b42318', medium: '#b54708', low: '#475467' };
const html = [];
html.push('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Website Audit Report</title>');
html.push('<style>body{font-family:system-ui,sans-serif;max-width:900px;margin:2rem auto;padding:0 1rem;color:#101828;line-height:1.5}h1{margin-bottom:.2rem}.card{border:1px solid #d0d5dd;border-radius:8px;padding:.8rem 1rem;margin:.6rem 0}.sev{font-weight:700;text-transform:uppercase;font-size:.8rem}.ev{background:#f2f4f7;padding:.3rem .5rem;border-radius:4px;font-family:monospace;font-size:.85rem;overflow-wrap:anywhere}.note{background:#fffaeb;border:1px solid #fedf89;padding:.7rem 1rem;border-radius:8px}</style></head><body>');
html.push('<h1>Website Quality &amp; Content Audit</h1>');
html.push('<p>Target: ' + esc(d.config.startUrl) + ' | ' + today + ' | Pages crawled: ' + d.stats.pagesCrawled + '</p>');
html.push('<p><strong>' + d.findings.length + ' findings</strong>: high ' + counts.high + ', medium ' + counts.medium + ', low ' + counts.low + '</p>');
html.push('<p class="note">' + esc(disclaimer) + '</p>');
html.push('<h2>Findings by page</h2>');
if (pageUrls.length === 0) html.push('<p>No findings from the automated rules.</p>');
pageUrls.forEach((u) => {
  html.push('<h3>' + esc(u) + '</h3>');
  byPage[u].forEach((f) => {
    html.push('<div class="card"><span class="sev" style="color:' + sevColor[f.severity] + '">' + esc(f.severity) + '</span> ' + esc(f.id) + ' ' + esc(f.rule) + ' (' + esc(f.category) + ')<br>' + esc(f.message) + '<div class="ev">' + esc(f.evidence) + '</div><small>Fix: ' + esc(f.fix) + '</small></div>');
  });
});
html.push('<h2>AI-assisted content review (unverified interpretation)</h2><p>' + esc(aiStatus) + '</p>');
if (ai) html.push('<pre style="white-space:pre-wrap">' + esc(ai) + '</pre><p><em>AI output may be wrong. Verify against the pages before acting.</em></p>');
html.push('<h2>Crawl notes</h2><ul>' + d.notes.map((n) => '<li>' + esc(n) + '</li>').join('') + '</ul></body></html>');

const issueDrafts = [];

return [{ json: {
  summary: { target: d.config.startUrl, pagesCrawled: d.stats.pagesCrawled, totalFindings: d.findings.length, bySeverity: counts, byCategory: cats },
  aiStatus: aiStatus,
  reportMarkdown: md.join('\n'),
  reportHtml: html.join('\n'),
  issueDrafts: issueDrafts
} }];

const crawl = $('Bounded Crawl & Rule Checks').first().json;
const findings = crawl.findings || [];
const rank = { high: 0, medium: 1, low: 2 };
const sevColor = { high: '#b42318', medium: '#b54708', low: '#475467' };
const disclaimer = 'Automated checks cover a subset of common issues and are not a full accessibility audit or WCAG certification. Verify each finding manually.';
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const uniq = (arr) => arr.filter((v, i) => arr.indexOf(v) === i);
const worst = (list) => list.map((f) => f.severity).sort((a, b) => rank[a] - rank[b])[0];
const labelsFor = (sev, cats) => ['website-audit', 'priority-' + sev].concat(cats.map((c) => 'area-' + c));
const make = (scope, title, list) => {
  const sev = worst(list);
  return { title: title, scope: scope, severity: sev, labels: labelsFor(sev, uniq(list.map((f) => f.category))), status: 'DRAFT - not published to GitHub', rules: uniq(list.map((f) => f.rule)), pages: uniq(list.map((f) => f.url)), findings: list, fixes: uniq(list.map((f) => f.fix)).slice(0, 5) };
};
const drafts = [];
const used = {};
const byRule = {};
findings.forEach((f) => { (byRule[f.rule] = byRule[f.rule] || []).push(f); });
Object.keys(byRule).forEach((rule) => {
  const list = byRule[rule];
  const pages = uniq(list.map((f) => f.url));
  if (pages.length >= 3) {
    drafts.push(make('site-wide', '[Website audit] ' + rule + ' on ' + pages.length + ' pages', list));
    list.forEach((f) => { used[f.id] = true; });
  }
});
const byPage = {};
findings.filter((f) => !used[f.id] && f.severity !== 'low').forEach((f) => { (byPage[f.url] = byPage[f.url] || []).push(f); });
Object.keys(byPage).forEach((u) => {
  const list = byPage[u];
  let path = u;
  try { path = new URL(u).pathname || '/'; } catch (e) {}
  drafts.push(make('page', '[Website audit] ' + list.length + ' issue(s) on ' + path, list));
  list.forEach((f) => { used[f.id] = true; });
});
const lows = findings.filter((f) => !used[f.id]);
if (lows.length > 0) {
  drafts.push(make('cleanup', '[Website audit] Low-priority cleanup (' + lows.length + ' findings)', lows));
}
drafts.sort((a, b) => rank[a.severity] - rank[b.severity]);
const renderDraft = (d, i) => {
  const h = [];
  h.push('<div class="card" style="page-break-inside:avoid">');
  h.push('<span class="sev" style="color:' + sevColor[d.severity] + '">' + esc(d.severity) + '</span> Draft ' + (i + 1) + ': ' + esc(d.title));
